const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Western Pacific Ocean region (tropical belt)
  const westernPacific = ee.Geometry.Rectangle([120, -20, 180, 20]);

  // 2. Get TRMM rainfall data for both years
  const trmm1998 = ee.ImageCollection('TRMM/3B43V7')
    .filterDate('1998-01-01', '1998-12-31')
    .filterBounds(westernPacific);

  const trmm2009 = ee.ImageCollection('TRMM/3B43V7')
    .filterDate('2009-01-01', '2009-12-31')
    .filterBounds(westernPacific);

  // Check if collections are empty
  const size1998 = trmm1998.size().getInfo();
  const size2009 = trmm2009.size().getInfo();

  console.log(`1998 Images: ${size1998}`);
  console.log(`2009 Images: ${size2009}`);

  if (size1998 === 0 || size2009 === 0) {
    console.log('Missing data for one or both years.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Calculate mean rainfall for each year
  const mean1998 = trmm1998.mean().select('precipitation');
  const mean2009 = trmm2009.mean().select('precipitation');

  // 4. Calculate regional statistics
  const stats1998 = mean1998.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: westernPacific,
    scale: 25000,
    maxPixels: 1e9
  }).getInfo();

  const stats2009 = mean2009.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: westernPacific,
    scale: 25000,
    maxPixels: 1e9
  }).getInfo();

  const rainfall1998 = stats1998.precipitation_mean;
  const rainfall2009 = stats2009.precipitation_mean;
  const count1998 = stats1998.precipitation_count;
  const count2009 = stats2009.precipitation_count;

  console.log(`1998 Rainfall: ${rainfall1998} mm/hr, Pixels: ${count1998}`);
  console.log(`2009 Rainfall: ${rainfall2009} mm/hr, Pixels: ${count2009}`);

  // 5. Validation and final answer
  if (count1998 === 0 || count2009 === 0) {
    console.log('No valid pixels found.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (rainfall1998 === null || rainfall1998 === undefined || 
      rainfall2009 === null || rainfall2009 === undefined ||
      isNaN(rainfall1998) || isNaN(rainfall2009)) {
    console.log('Calculation failed - invalid values.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Check for unrealistic values (rainfall rate in mm/hr should be 0-50)
  if (rainfall1998 < 0 || rainfall1998 > 100 || 
      rainfall2009 < 0 || rainfall2009 > 100) {
    console.log('Invalid rainfall values detected.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare rainfall rates
  const increase = rainfall2009 - rainfall1998;
  console.log(`Difference (2009 - 1998): ${increase.toFixed(4)} mm/hr`);

  if (rainfall2009 > rainfall1998) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
